#include "gui/Fonts.h"

#include <cstddef>
#include <string>

#include "core/Assets.h"
#include "gui/Theme.h"

// Generated by cmake/Bin2c.cmake from gui/fonts/*.ttf.
extern "C" {
extern const unsigned char supple_font_inter_regular[];
extern const size_t supple_font_inter_regular_size;
extern const unsigned char supple_font_inter_semibold[];
extern const size_t supple_font_inter_semibold_size;
extern const unsigned char supple_font_plex_mono_regular[];
extern const size_t supple_font_plex_mono_regular_size;
extern const unsigned char supple_font_plex_mono_medium[];
extern const size_t supple_font_plex_mono_medium_size;
extern const unsigned char supple_font_plex_sans_condensed_semibold[];
extern const size_t supple_font_plex_sans_condensed_semibold_size;
}

namespace supple::gui {

bool loadFace(NVGcontext* vg, const char* name, const unsigned char* data, size_t size) {
    if (nvgFindFont(vg, name) >= 0) return true;
    // NanoVG reads the data in place and, with freeData 0, never frees it.
    if (nvgCreateFontMem(vg, name, const_cast<unsigned char*>(data), static_cast<int>(size), 0) < 0 &&
        nvgCreateFontMem(vg, name, const_cast<unsigned char*>(supple_font_inter_regular),
                         static_cast<int>(supple_font_inter_regular_size), 0) < 0)
        return false;
    nvgAddFallbackFont(vg, name, font::kUi);
    return true;
}

bool loadFonts(NVGcontext* vg) {
    struct Face {
        const char* name;
        const unsigned char* data;
        size_t size;
    };
    const Face faces[] = {
        {font::kUi, supple_font_inter_regular, supple_font_inter_regular_size},
        {font::kUiBold, supple_font_inter_semibold, supple_font_inter_semibold_size},
        {font::kMono, supple_font_plex_mono_regular, supple_font_plex_mono_regular_size},
        {font::kMonoMedium, supple_font_plex_mono_medium, supple_font_plex_mono_medium_size},
        {font::kDisplay, supple_font_plex_sans_condensed_semibold, supple_font_plex_sans_condensed_semibold_size},
    };
    for (const Face& f : faces) {
        if (nvgFindFont(vg, f.name) >= 0) continue;
        // NanoVG reads the data in place and, with freeData 0, never frees it.
        if (nvgCreateFontMem(vg, f.name, const_cast<unsigned char*>(f.data), static_cast<int>(f.size), 0) < 0)
            return false;
    }
    nvgAddFallbackFont(vg, font::kMono, font::kUi);
    nvgAddFallbackFont(vg, font::kMonoMedium, font::kUiBold);
    nvgAddFallbackFont(vg, font::kDisplay, font::kUiBold);
    // The product's own faces (PRODUCT_ASSETS), by file stem: "Orbitron.ttf"
    // is the face "Orbitron", falling back to Inter for what it lacks.
    for (size_t i = 0; i < assets::count(); ++i) {
        const assets::Asset a = assets::at(i);
        if (!assets::hasExtension(a.name, ".ttf") && !assets::hasExtension(a.name, ".otf")) continue;
        const std::string face(a.name.substr(0, a.name.size() - 4));
        if (!loadFace(vg, face.c_str(), a.data, a.size)) return false;
    }
    return true;
}

}  // namespace supple::gui
